/* Pedagogical AI, image OCR, voice input and offline quick reference. */
let buddyTurns=[],activeBuddyMode='study';
let activeRecognition=null,currentStudyLesson=null,currentStudySignature='';
let ttsEnabled=localStorage.getItem('buddy-tts-enabled')==='1';
function stopBuddySpeech(){if('speechSynthesis'in window)window.speechSynthesis.cancel()}
function speakBuddy(text){if(!ttsEnabled||!('speechSynthesis'in window)||!text)return;stopBuddySpeech();const u=new SpeechSynthesisUtterance(text);u.lang=activeBuddyMode==='tour'?'en-US':'vi-VN';u.rate=.92;u.pitch=1;const voices=window.speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang&&v.lang.toLowerCase().startsWith('vi'))||null;window.speechSynthesis.speak(u)}
function toggleBuddySpeech(){ttsEnabled=!ttsEnabled;localStorage.setItem('buddy-tts-enabled',ttsEnabled?'1':'0');if(!ttsEnabled)stopBuddySpeech();const b=$('#ttsToggle');if(b){b.textContent=ttsEnabled?'🔊 Tắt đọc':'🔈 Bật đọc';b.setAttribute('aria-pressed',String(ttsEnabled))}const last=[...buddyTurns].reverse().find(x=>x.role==='assistant');if(ttsEnabled&&last)speakBuddy(last.text)}
function generatedMathLessons(g){const out=[],add=(q,a,b,c,id)=>out.push({question:q,steps:[a,b,c],id:`${g}-generated-${id}`});for(let i=1;i<=40;i++){const x=i+2,a=i%4+2,b=i+3,c=a*x+b;if(g===6){add(`Tìm x: ${a}x + ${b} = ${c}`,`Muốn giữ phần có x riêng, em cần xử lý số ${b} trước. Hãy chọn phép tính làm ở cả hai vế.`,`Trừ ${b} ở cả hai vế để được ${a}x = ${c-b}. Em hãy chia tiếp hai vế cho ${a}.`,`x = ${x}. Thay lại: ${a} × ${x} + ${b} = ${c}.`,`eq-${i}`);const w=i+4,h=i+2;add(`Hình chữ nhật dài ${w} cm, rộng ${h} cm. Tính chu vi.`,`Nhắc lại: chu vi hình chữ nhật bằng hai lần tổng chiều dài và chiều rộng. Em hãy viết phép tính trong ngoặc.`,`Tổng hai cạnh là ${w} + ${h} = ${w+h}. Bây giờ nhân kết quả với 2.`,`Chu vi là 2 × ${w+h} = ${2*(w+h)} cm.`,`geo-${i}`)}else if(g===7){const k=i+2;add(`Tìm x biết x/${k} = ${i+1}/${k+1}.`,`Đây là tỉ lệ thức. Em hãy nhân chéo hai tích trước.`,`Ta có (${k+1})x = ${k*(i+1)}. Hãy chia hai vế cho ${k+1}.`,`x = ${k*(i+1)}/${k+1}. Có thể rút gọn phân số nếu cần.`,`ratio-${i}`);const price=(i+2)*100,percent=(i%4+1)*5;add(`Một món đồ giá ${price}.000 đồng được giảm ${percent}%. Tính số tiền được giảm.`,`Đổi ${percent}% thành phân số trên 100 rồi nhân với giá ban đầu.`,`Số tiền giảm là ${price*1000} × ${percent}/100. Em hãy thực hiện phép nhân và phép chia.`,`Số tiền được giảm là ${price*percent*10} đồng.`,`pct-${i}`)}else if(g===8){const rhs=a*(x-i)+b;add(`Giải phương trình ${a}(x − ${i}) + ${b} = ${rhs}`,`Khai triển vế trái bằng tính chất phân phối. Đừng chia ngay khi còn ngoặc.`,`Sau khi khai triển, chuyển ${b} và −${a*i} sang vế phải để giữ ${a}x riêng.`,`Phương trình có nghiệm x = ${x}. Hãy thay lại để kiểm tra.`,`linear-${i}`);const n=i+2,m=i+3;add(`Phân tích x² − ${n+m}x + ${n*m} thành nhân tử.`,`Tìm hai số có tổng bằng ${n+m} và tích bằng ${n*m}.`,`Hai số đó là ${n} và ${m}. Hãy viết thành tích hai nhị thức.`,`x² − ${n+m}x + ${n*m} = (x − ${n})(x − ${m}).`,`factor-${i}`)}else if(g===9){const y=i+1,sum=x+y,diff=x-y;add(`Giải hệ x + y = ${sum}; x − y = ${diff}.`,`Cộng hai phương trình để khử y. Em hãy tính vế trái và vế phải sau khi cộng.`,`Ta được 2x = ${2*x}. Hãy tìm x rồi thay vào phương trình đầu để tìm y.`,`Nghiệm của hệ là (x; y) = (${x}; ${y}).`,`system-${i}`);const n=i+1,m=i+2;add(`Giải phương trình x² − ${n+m}x + ${n*m} = 0.`,`Tìm hai số có tổng ${n+m} và tích ${n*m} để phân tích vế trái.`,`Vế trái bằng (x − ${n})(x − ${m}). Hãy cho từng thừa số bằng 0.`,`Phương trình có hai nghiệm x = ${n} và x = ${m}.`,`quad-${i}`)}else if(g===10){const n=i+1,m=i+3;add(`Giải bất phương trình (x − ${n})(x − ${m}) < 0.`,`Xác định hai nghiệm biên ${n} và ${m}, rồi xét dấu tích trên ba khoảng.`,`Hệ số của x² dương nên tích âm ở khoảng nằm giữa hai nghiệm.`,`Tập nghiệm là ${n} < x < ${m}.`,`ineq-${i}`);const u=i+1,v=i+2,p=i+3,q=-(i+1);add(`Cho vectơ a = (${u}; ${v}), b = (${p}; ${q}). Tính a·b.`,`Tích vô hướng bằng tích các hoành độ cộng tích các tung độ. Em hãy viết phép tính.`,`a·b = ${u}×${p} + ${v}×(${q}). Hãy tính hai tích trước.`,`a·b = ${u*p+v*q}.`,`vector-${i}`)}else if(g===11){const first=i+1,d=i+2,n=6;add(`Cấp số cộng có u₁ = ${first}, công sai d = ${d}. Tính u₆.`,`Dùng công thức uₙ = u₁ + (n − 1)d. Hãy thay n = 6.`,`u₆ = ${first} + 5 × ${d}. Em hãy tính phép nhân trước.`,`u₆ = ${first+5*d}.`,`seq-${i}`);const total=i+5,choose=2;add(`Có ${total} học sinh. Có bao nhiêu cách chọn ${choose} bạn?`,`Vì không xét thứ tự, em dùng tổ hợp C(${total}, ${choose}).`,`C(${total}, 2) = ${total}×${total-1}/2. Hãy thực hiện phép tính.`,`Có ${total*(total-1)/2} cách chọn.`,`comb-${i}`)}else if(g===12){const power=i%4+2,coef=i+1;add(`Tính đạo hàm f(x) = ${coef}x^${power} + ${i}.`,`Đạo hàm hằng số bằng 0. Với x^n, hạ số mũ xuống làm hệ số.`,`f′(x) = ${coef} × ${power} × x^${power-1}. Em hãy nhân hai hệ số.`,`f′(x) = ${coef*power}x^${power-1}.`,`derivative-${i}`);const p=i%3+1;add(`Tính ∫₀¹ ${p+1}x^${p} dx.`,`Tăng số mũ thêm 1 rồi chia cho số mũ mới để tìm nguyên hàm.`,`Một nguyên hàm là x^${p+1}. Hãy thay cận 1 và 0.`,`Giá trị tích phân bằng 1.`,`integral-${i}`)}}return out}
function lessonPool(){
 const base=subject==='Toán'?mathLessonsByGrade[grade]:(lessons[level][subject]||lessons[level]['Toán']);
 const rows=subject==='Toán'?(mathBanksByGrade[grade]||[]):((banks[level]&&banks[level][subject])||[]);
 const extras=rows.map((row,i)=>({question:row[0]+' '+row[1].map((x,n)=>`${String.fromCharCode(65+n)}. ${x}`).join(' · '),steps:[`Đọc kỹ đề và xác định kiến thức cần dùng. Em hãy loại trước một lựa chọn chắc chắn chưa đúng.`,`So sánh các lựa chọn còn lại bằng cách thực hiện một phép tính hoặc tìm từ khóa quan trọng. Em chọn phương án nào?`,row[3]],id:`${grade}-${subject}-${i}`}));
 return [{...base,id:`${grade}-${subject}-sample`},...extras,...(subject==='Toán'?generatedMathLessons(grade):[])];
}
function chooseStudyLesson(force=false){const signature=`${grade}-${subject}`;const pool=lessonPool();if(!force&&currentStudyLesson&&currentStudySignature===signature)return currentStudyLesson;const previous=currentStudyLesson?.id;const choices=pool.filter(x=>x.id!==previous);currentStudyLesson=choices[Math.floor(Math.random()*choices.length)]||pool[0];currentStudySignature=signature;step=0;return currentStudyLesson}
const offlineReference={version:1,formulas:[
 {grade:'6–7',title:'Tỉ lệ thức',value:'a / b = c / d  ⇒  a × d = b × c'},
 {grade:'7–9',title:'Pythagore',value:'Trong tam giác vuông: a² + b² = c²'},
 {grade:'8–9',title:'Hằng đẳng thức',value:'(a + b)² = a² + 2ab + b²'},
 {grade:'8–9',title:'Phương trình bậc nhất',value:'ax + b = 0  ⇒  x = −b/a (a ≠ 0)'},
 {grade:'10–12',title:'Phương trình bậc hai',value:'Δ = b² − 4ac; x = (−b ± √Δ) / 2a'},
 {grade:'10–12',title:'Đạo hàm lũy thừa',value:"(xⁿ)' = n·xⁿ⁻¹"}
],examples:[
 '2x + 5 = 17: bước đầu hãy chuyển 5 sang vế phải.',
 '(x − 2)/3 + (x + 1)/2 = 4: bước đầu hãy tìm BCNN của 3 và 2.',
 'Tam giác vuông có hai cạnh góc vuông: bắt đầu bằng định lý Pythagore.'
]};
try{localStorage.setItem('buddy-offline-reference-v1',JSON.stringify(offlineReference))}catch{}
function renderOfflineReference(){const rows=offlineReference.formulas.filter(x=>grade<=9?!x.grade.startsWith('10'):x.grade.startsWith('10'));return `<details class="offline-reference"><summary>⌁ Công thức & bài mẫu dùng khi mất mạng</summary><div class="offline-reference-grid">${rows.map(x=>`<article><small>${x.grade}</small><b>${x.title}</b><code>${x.value}</code></article>`).join('')}</div><p>Dữ liệu này đã được lưu trên thiết bị và có thể mở lại khi mạng yếu.</p></details>`}
const haGiangLessonGuides={
 'Lũng Cú':{question:'Cột cờ Lũng Cú nằm ở đâu và có ý nghĩa gì đối với Hà Giang?',steps:['Trước tiên, em hãy xác định Lũng Cú thuộc huyện nào của tỉnh Hà Giang.','Quan sát vị trí sát biên giới và hình ảnh lá cờ. Theo em, hai chi tiết đó gợi lên điều gì?','Gộp hai ý trên thành 2–3 câu: vị trí ở huyện Đồng Văn và ý nghĩa về chủ quyền, niềm tự hào dân tộc.'],answer:'Cột cờ Lũng Cú nằm tại xã Lũng Cú, huyện Đồng Văn, tỉnh Hà Giang. Công trình là biểu tượng thiêng liêng của chủ quyền quốc gia ở cực Bắc và thể hiện niềm tự hào, tinh thần đoàn kết của nhân dân Việt Nam.'},
 'Đồng Văn':{question:'Địa hình đặc trưng của Cao nguyên đá Đồng Văn là gì?',steps:['Hãy nhìn tên “cao nguyên đá” và xác định loại đá xuất hiện phổ biến ở đây.','Đá vôi bị nước hòa tan lâu ngày tạo nên địa hình karst. Em hãy nêu một dấu hiệu dễ nhận thấy của kiểu địa hình này.','Liên hệ đời sống: người dân phải thích nghi thế nào với đất ít, đá nhiều và thiếu nước?'],answer:'Cao nguyên đá Đồng Văn nổi bật với địa hình karst trên nền đá vôi, gồm núi đá tai mèo, hẻm vực và các thung lũng nhỏ. Do đất canh tác và nước khan hiếm, người dân tận dụng hốc đá, giữ đất và nước để trồng trọt, đồng thời phát triển sinh kế phù hợp với vùng núi đá.'},
 'Mèo Vạc':{question:'Đèo Mã Pí Lèng, sông Nho Quế và hẻm Tu Sản liên hệ với nhau như thế nào?',steps:['Trước tiên, em hãy xác định đâu là đèo, đâu là sông và đâu là hẻm vực.','Hãy mô tả vị trí: con đèo ở cao, sông chảy phía dưới và hẻm Tu Sản nằm giữa các vách núi đá.','Từ cảnh quan đó, em hãy nêu một việc du khách cần làm để bảo vệ môi trường nơi đây.'],answer:'Đèo Mã Pí Lèng nằm trên sườn núi cao, nhìn xuống sông Nho Quế chảy qua hẻm Tu Sản giữa những vách đá dựng đứng. Ba yếu tố tạo thành cảnh quan đặc trưng của Mèo Vạc. Du khách cần không xả rác, không phá hoại cảnh quan và tuân thủ quy định an toàn.'},
 'Quản Bạ':{question:'Núi Đôi Quản Bạ có giá trị gì đối với cảnh quan và văn hóa Hà Giang?',steps:['Hãy bắt đầu bằng việc mô tả hình dáng nổi bật của Núi Đôi bằng một câu ngắn.','Tiếp theo, phân biệt hai loại giá trị: giá trị cảnh quan tự nhiên và giá trị trong truyền thuyết địa phương.','Viết 2–3 câu kết nối cảnh đẹp, câu chuyện dân gian và ý thức giữ gìn cảnh quan.'],answer:'Núi Đôi Quản Bạ có hai ngọn núi tròn, cân đối và nổi bật giữa thung lũng. Đây vừa là cảnh quan tự nhiên đặc sắc, vừa gắn với truyền thuyết dân gian của cộng đồng địa phương. Vì vậy, Núi Đôi có giá trị về du lịch, văn hóa và cần được bảo vệ.'},
 'Hoàng Su Phì':{question:'Ruộng bậc thang Hoàng Su Phì giúp người dân canh tác trên sườn núi ra sao?',steps:['Hãy tưởng tượng sườn núi dốc. Nếu trồng lúa trực tiếp trên mặt dốc, đất và nước sẽ gặp vấn đề gì?','Các bậc ruộng tạo mặt tương đối bằng để giữ nước và hạn chế đất bị cuốn trôi. Em hãy diễn đạt lại bằng lời của mình.','Nêu thêm một giá trị của ruộng bậc thang đối với văn hóa hoặc du lịch Hà Giang.'],answer:'Ruộng bậc thang chia sườn núi dốc thành nhiều mặt ruộng tương đối bằng, giúp giữ nước, giữ đất và hạn chế xói mòn để trồng lúa. Đây cũng là kết quả của kinh nghiệm lao động lâu đời, tạo nên cảnh quan văn hóa và điểm du lịch nổi bật của Hoàng Su Phì.'},
 'TP Hà Giang':{question:'Vị trí thành phố Hà Giang có vai trò gì trong kết nối các vùng của tỉnh?',steps:['Trước tiên, em hãy xác định thành phố Hà Giang là trung tâm hành chính của tỉnh.','Từ thành phố, các tuyến đường đi tới những huyện vùng cao. Điều đó hỗ trợ việc đi lại và trao đổi hàng hóa thế nào?','Tóm tắt vai trò của thành phố bằng ba ý: hành chính, giao thông và dịch vụ.'],answer:'Thành phố Hà Giang là trung tâm hành chính, kinh tế và dịch vụ của tỉnh. Các tuyến giao thông từ đây kết nối với nhiều huyện vùng cao, hỗ trợ đi lại, trao đổi hàng hóa, học tập, chăm sóc sức khỏe và phát triển du lịch.'}
};
function buddyChatHTML(){return `<section class="panel buddy-chat"><div class="panel-head"><div><span class="eyebrow">SMART BUDDY BOT</span><h2>Hỏi từng bước</h2></div><div class="chat-head-actions"><button class="secondary compact" type="button" id="ttsToggle" aria-pressed="${ttsEnabled}">${ttsEnabled?'🔊 Tắt đọc':'🔈 Bật đọc'}</button><span class="privacy-chip">🔒 API ở máy chủ</span></div></div><div class="chat-transcript" id="chatTranscript" aria-live="polite">${buddyTurns.length?buddyTurns.map(t=>`<div class="chat-message ${t.role}"><b>${t.role==='user'?'Bạn':'Buddy'}</b><p>${esc(t.text)}</p></div>`).join(''):'<div class="chat-empty">Bạn có thể gõ, đọc câu hỏi bằng giọng nói hoặc chụp đề bài.</div>'}</div><div class="notice">Buddy không đưa đáp số ngay. Mỗi lượt chỉ có một gợi ý và một câu hỏi để bạn làm tiếp.</div><label class="habit"><input id="ageConfirmed" type="checkbox"><span>Tôi từ 13 tuổi trở lên</span></label><form class="chat-composer" id="askForm"><label class="sr" for="askInput">Câu hỏi của bạn</label><textarea id="askInput" maxlength="1000" rows="3" placeholder="Hãy hỏi về địa danh hoặc bài học em chưa hiểu"></textarea><div class="input-tools"><label class="input-tool" for="problemImage">▧ Chụp/tải đề<input id="problemImage" type="file" accept="image/png,image/jpeg,image/webp" capture="environment"></label><button class="input-tool" type="button" id="voiceInput" aria-pressed="false">◉ Nói câu hỏi</button><span id="inputStatus" role="status"></span><button class="primary send-ai" type="submit">Gửi cho Buddy ↗</button></div></form><div class="notice" id="askStatus" role="status">Đang kiểm tra kết nối AI…</div></section>`}
function bindBuddyChat(){$('#askForm').onsubmit=sendAIQuestion;$('#problemImage').onchange=readProblemImage;$('#voiceInput').onclick=startVoiceInput;$('#ttsToggle').onclick=toggleBuddySpeech;checkAIStatus()}
function renderHaGiangLesson(p){const guide=haGiangLessonGuides[p.place]||haGiangLessonGuides['Đồng Văn'];subject='Địa lý Hà Giang';lessonContext={title:`${p.place}, Hà Giang: ${guide.question}`,hint:guide.steps[step],answer:guide.answer};content.innerHTML=`<h1>Khám phá ${p.place}, Hà Giang ✧</h1><p class="muted">Bài học địa phương gắn với chính địa danh em vừa chọn trên bản đồ.</p><div class="workspace study-workspace"><div class="tabs"><button class="chip selected">GDĐP Hà Giang</button><button class="chip" id="backToMap">← Chọn địa danh khác</button></div><section class="panel lesson-card"><span class="eyebrow">BÀI HỌC ĐỊA PHƯƠNG · HÀ GIANG</span><h2>${guide.question}</h2><div class="bubble lesson-hint" aria-live="polite">${guide.steps[step]}</div><div class="local-response-box"><label for="localStudentAnswer"><b>Câu trả lời của em</b><span>Viết bằng lời của em, Smart Buddy sẽ chấm và góp ý.</span></label><textarea id="localStudentAnswer" rows="5" maxlength="1500" placeholder="Em trả lời ở đây..."></textarea><label class="habit"><input id="ageConfirmed" type="checkbox"><span>Tôi từ 13 tuổi trở lên</span></label><div class="actions"><button class="primary" id="gradeLocalAnswer">Nhờ Smart Buddy chấm ✓</button></div><div class="notice" id="localGradeResult" role="status">Nhập câu trả lời, xác nhận độ tuổi rồi nhờ Buddy chấm.</div></div>${step===2?`<details class="offline-reference local-answer"><summary>✓ Xem câu trả lời tham khảo</summary><div class="bubble"><b>Trả lời:</b> ${guide.answer}</div></details>`:''}<div class="actions"><button class="primary" id="nextStep">${step<2?'Xem gợi ý tiếp theo →':'Học lại từ bước đầu ↺'}</button><button class="secondary" id="backToMap2">Khám phá nơi khác</button></div></section></div>`;$('#nextStep').onclick=()=>{step=(step+1)%3;render()};$('#gradeLocalAnswer').onclick=()=>gradeStudyAnswer(guide,'Địa lý Hà Giang');const back=()=>{window.buddyLocalLesson=null;step=0;buddyTurns=[];navigate('localstudy')};$('#backToMap').onclick=back;$('#backToMap2').onclick=back}
function studentAnswerHTML(){return `<div class="local-response-box"><label for="localStudentAnswer"><b>Câu trả lời của em</b><span>Viết bằng lời của em, Smart Buddy sẽ chấm và góp ý.</span></label><textarea id="localStudentAnswer" rows="5" maxlength="1500" placeholder="Em trả lời ở đây..."></textarea><label class="habit"><input id="ageConfirmed" type="checkbox"><span>Tôi từ 13 tuổi trở lên</span></label><div class="actions"><button class="primary" id="gradeLocalAnswer">Nhờ Smart Buddy chấm ✓</button></div><div class="notice" id="localGradeResult" role="status">Nhập câu trả lời, xác nhận độ tuổi rồi nhờ Buddy chấm.</div></div>`}
async function gradeStudyAnswer(guide,gradingSubject){const input=$('#localStudentAnswer'),result=$('#localGradeResult'),button=$('#gradeLocalAnswer'),answer=input.value.trim();if(answer.length<2){result.textContent='Em hãy nhập câu trả lời rồi gửi nhé.';return}if(!$('#ageConfirmed').checked){result.textContent='Hãy tích “Tôi từ 13 tuổi trở lên” ở khung Smart Buddy bên dưới trước nhé.';return}button.disabled=true;button.textContent='Buddy đang chấm…';result.textContent='Đang đối chiếu ý chính và cách trình bày…';try{const r=await fetch('/api/ask',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:answer,mode:'grade',level,grade,subject:gradingSubject,context:{title:guide.question,answer:guide.answer||guide.steps?.[2]||''},turns:[],ageConfirmed:true}),signal:AbortSignal.timeout(85000)});const data=await r.json();if(!r.ok)throw Error(data.message||'Chưa chấm được bài.');result.innerHTML=`<b>Nhận xét của Smart Buddy</b><p>${esc(data.answer)}</p>`}catch(err){result.textContent=err.name==='TimeoutError'||err.name==='TypeError'?'Kết nối lỗi hoặc quá thời gian chờ. Hãy thử lại.':err.message}finally{button.disabled=false;button.textContent='Nhờ Smart Buddy chấm ✓'}}
renderStudy=function(){
 if(window.buddyLocalLesson){renderHaGiangLesson(window.buddyLocalLesson);return}
 let l=chooseStudyLesson();lessonContext={title:l.question,hint:l.steps[step]};if(!lessons[level][subject]&&subject!=='Toán')subject='Toán';
 content.innerHTML=`<h1>Cùng nghĩ, cùng hiểu bài ✧</h1><p class="muted">Buddy chỉ gợi ý đúng một bước mỗi lượt để bạn tự tìm ra lời giải.</p><div class="workspace study-workspace"><div class="tabs">${['Toán','Ngữ văn','Lịch sử'].map(t=>`<button class="chip ${subject===t?'selected':''}" data-subject="${t}">${t}</button>`).join('')}</div><section class="panel lesson-card"><span class="eyebrow">BÀI MẪU · KHỐI ${grade}</span><h2>${l.question}</h2><div class="bubble lesson-hint" aria-live="polite">${l.steps[step]}</div>${studentAnswerHTML()}<div class="actions"><button class="primary" id="nextStep">${step<2?'Xem gợi ý tiếp theo →':'Thử lại từ đầu ↺'}</button><button class="secondary" id="newLesson">Bài khác ↻</button><button class="secondary" id="practice">Luyện câu hỏi cùng môn</button></div></section>${renderOfflineReference()}</div>`;
 document.querySelectorAll('[data-subject]').forEach(b=>b.onclick=()=>{window.buddyLocalLesson=null;subject=b.dataset.subject;step=0;buddyTurns=[];render()});
 $('#nextStep').onclick=()=>{step=(step+1)%3;render()};$('#newLesson').onclick=()=>{chooseStudyLesson(true);buddyTurns=[];render()};$('#practice').onclick=()=>{question=0;score=0;answered=false;navigate('quiz')};
 $('#gradeLocalAnswer').onclick=()=>gradeStudyAnswer({question:l.question,steps:l.steps},subject);
};
async function readProblemImage(e){const file=e.target.files?.[0],status=$('#inputStatus'),input=$('#askInput');if(!file)return;if(!/^image\/(png|jpeg|webp)$/.test(file.type)||file.size>5*1024*1024){status.textContent='Ảnh phải là PNG/JPG/WEBP và không quá 5 MB.';return}if(!$('#ageConfirmed').checked){status.textContent='Hãy xác nhận độ tuổi trước khi gửi ảnh.';return}status.textContent='Đang đọc chữ trong ảnh…';try{const fileData=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(file)});const res=await fetch('/api/tools',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'ocr',grade,ageConfirmed:true,fileData,fileType:file.type}),signal:AbortSignal.timeout(60000)});const data=await res.json();if(!res.ok)throw Error(data.message||'Không đọc được ảnh.');input.value=[input.value.trim(),data.result].filter(Boolean).join('\n');status.textContent='Đã chép đề từ ảnh. Bạn hãy kiểm tra lại ký hiệu.'}catch(err){status.textContent=err.name==='TimeoutError'||err.name==='TypeError'?'Kết nối lỗi khi đọc ảnh.':err.message}finally{e.target.value=''}}
function startVoiceInput(){const button=$('#voiceInput'),status=$('#inputStatus'),input=$('#askInput');if(activeRecognition){activeRecognition.stop();return}const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){status.textContent='Trình duyệt này chưa hỗ trợ nhập giọng nói. Bạn có thể dùng bàn phím giọng nói của điện thoại.';return}const r=new SR();activeRecognition=r;r.lang='vi-VN';r.interimResults=false;r.continuous=true;r.maxAlternatives=1;button.textContent='■ Tắt nói';button.setAttribute('aria-pressed','true');status.textContent='Đang nghe… Nhấn “Tắt nói” khi xong.';r.onresult=e=>{let text='';for(let i=e.resultIndex;i<e.results.length;i++)if(e.results[i].isFinal)text+=e.results[i][0].transcript+' ';if(text.trim())input.value=[input.value.trim(),text.trim()].filter(Boolean).join(' ')};r.onerror=e=>{if(e.error!=='aborted')status.textContent='Chưa nghe rõ. Hãy thử lại ở nơi yên tĩnh.'};r.onend=()=>{activeRecognition=null;if(button.isConnected){button.textContent='◉ Nói câu hỏi';button.setAttribute('aria-pressed','false')}if(status.textContent.startsWith('Đang nghe'))status.textContent=input.value.trim()?'Đã dừng nói và nhập nội dung.':'Đã tắt nói.'};r.start()}
sendAIQuestion=async function(e){e.preventDefault();const form=e.currentTarget,input=$('#askInput'),status=$('#askStatus'),q=input.value.trim();if(!q){status.textContent='Bạn hãy nhập câu hỏi trước nhé.';return}if(!$('#ageConfirmed').checked){status.textContent='Phần AI dành cho người từ 13 tuổi trở lên.';return}const button=form.querySelector('.send-ai');button.disabled=true;button.textContent='Đang suy nghĩ…';status.className='notice';status.textContent='Buddy đang chọn đúng một bước gợi ý…';const history=buddyTurns.slice(-8).map(x=>({role:x.role,text:x.text}));try{const r=await fetch('/api/ask',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q,mode:activeBuddyMode,level,grade,subject,context:lessonContext,turns:history,ageConfirmed:true}),signal:AbortSignal.timeout(85000)});let data;try{data=await r.json()}catch{throw Error('Máy chủ AI chưa trả dữ liệu hợp lệ.')}if(!r.ok)throw Error(data.message||'Máy chủ gặp lỗi.');if(typeof data.answer!=='string'||!data.answer.trim())throw Error('AI chưa trả lời. Hãy thử lại.');buddyTurns.push({role:'user',text:q},{role:'assistant',text:data.answer.trim()});buddyTurns=buddyTurns.slice(-10);input.value='';const transcript=$('#chatTranscript');transcript.innerHTML=buddyTurns.map(t=>`<div class="chat-message ${t.role}"><b>${t.role==='user'?'Bạn':'Buddy'}</b><p>${esc(t.text)}</p></div>`).join('');transcript.scrollTop=transcript.scrollHeight;speakBuddy(data.answer.trim());status.textContent='Buddy đã gợi ý một bước. Bạn hãy thử làm rồi trả lời tiếp.'}catch(err){status.textContent=err.name==='TimeoutError'||err.name==='TypeError'?'Kết nối lỗi hoặc quá thời gian chờ. Hãy kiểm tra mạng rồi thử lại.':err.message}finally{if(button.isConnected){button.disabled=false;button.textContent='Gửi cho Buddy ↗'}}};

function renderBuddySpace(){activeBuddyMode='study';window.buddyLocalLesson=null;lessonContext={title:`Câu hỏi tự do môn ${subject}, khối ${grade}`,hint:'Hãy hỏi một vấn đề em chưa hiểu; Buddy sẽ gợi ý từng bước.'};content.innerHTML=`<span class="eyebrow">KHÔNG GIAN TRỢ LÝ AI RIÊNG</span><h1>Smart Buddy Bot ✧</h1><p class="muted">Hỏi bài bằng chữ, giọng nói hoặc ảnh. Buddy gợi ý từng bước để em tự tìm ra cách làm.</p><div class="workspace buddy-space"><div class="tabs">${['Toán','Ngữ văn','Lịch sử','Địa lý Hà Giang'].map(t=>`<button class="chip ${subject===t?'selected':''}" data-buddy-subject="${t}">${t}</button>`).join('')}</div>${buddyChatHTML()}<div class="actions buddy-shortcuts"><button class="secondary" data-go="study">Mở bài học & tự trả lời</button><button class="secondary" data-go="quiz">Mở luyện đề</button></div></div>`;document.querySelectorAll('[data-buddy-subject]').forEach(b=>b.onclick=()=>{subject=b.dataset.buddySubject;buddyTurns=[];render()});bindBuddyChat();bindCommon()}
function renderTourGuide(){activeBuddyMode='tour';subject='Ha Giang Tour Guide';lessonContext={title:'Practice introducing Ha Giang as a tour guide',hint:'Use simple English. The visitor will ask one question at a time and help correct grammar.'};content.innerHTML=`<span class="eyebrow">ENGLISH FOR LOCAL TOURISM</span><h1>Ha Giang Tour Guide ◈</h1><p class="muted">Đóng vai hướng dẫn viên, luyện giới thiệu Hà Giang bằng tiếng Anh đơn giản và nhận góp ý ngữ pháp từ AI.</p><div class="workspace tour-space"><section class="panel tour-intro"><div class="tour-place-grid">${[['Lũng Cú','Lung Cu Flag Tower'],['Đồng Văn','Dong Van Karst Plateau'],['Mèo Vạc','Ma Pi Leng Pass'],['Nho Quế','Nho Que River']].map(x=>`<button class="tour-place" data-tour-prompt="I would like to introduce ${x[1]}."><b>${x[0]}</b><span>${x[1]}</span></button>`).join('')}</div><div class="bubble tour-mission"><b>Your mission:</b> Introduce one place in 2–4 simple English sentences. Buddy will act as a tourist, correct one important grammar mistake, and ask the next question.</div></section>${buddyChatHTML()}<div class="notice">Gợi ý mở đầu: “Welcome to Ha Giang.” · “This place is famous for…” · “Visitors can…”</div></div>`;const input=$('#askInput');input.placeholder='Example: Welcome to Ha Giang. Today I will introduce Ma Pi Leng Pass.';document.querySelectorAll('[data-tour-prompt]').forEach(b=>b.onclick=()=>{input.value=b.dataset.tourPrompt;input.focus()});bindBuddyChat();bindCommon()}
const mnemonicSamples={tho:'Quê hương là chùm khế ngọt\nCho con trèo hái mỗi ngày',lichsu:'Dân ta phải biết sử ta\nCho tường gốc tích nước nhà Việt Nam',tienganh:'Practice makes progress\nEvery small step matters'};
function initialCipher(text){return text.split(/\r?\n/).map(line=>(line.match(/[\p{L}\p{N}]+/gu)||[]).map(word=>word[0].toLocaleUpperCase('vi-VN')).join(' · ')).join('\n')}
function renderMnemonic(){const saved=localStorage.getItem('buddy-mnemonic-text')||'';content.innerHTML=`<span class="eyebrow">MEMORY CODE</span><h1>Góc ghi nhớ chữ cái đầu Aa</h1><p class="muted">Biến thơ hoặc đoạn văn thành chuỗi chữ cái đầu để luyện nhớ như giải một mật mã.</p><div class="mnemonic-layout"><section class="panel"><div class="mode-switch"><button class="chip" data-memory-sample="tho">Thơ tiếng Việt</button><button class="chip" data-memory-sample="lichsu">Lịch sử</button><button class="chip" data-memory-sample="tienganh">Tiếng Anh</button></div><label for="memoryText"><b>Đoạn cần học thuộc</b></label><textarea id="memoryText" maxlength="5000" rows="10" placeholder="Dán bài thơ hoặc đoạn văn vào đây...">${esc(saved)}</textarea><div class="actions"><button class="primary" id="makeMemoryCode">Tạo mật mã chữ cái đầu ↗</button><button class="secondary" id="clearMemory">Xóa</button></div><div class="notice">Mỗi dòng trong văn bản gốc sẽ được giữ thành một dòng mật mã riêng.</div></section><section class="panel memory-result-panel"><div class="panel-head"><h2>Mật mã ghi nhớ</h2><button class="secondary compact" id="copyMemory" disabled>Sao chép</button></div><pre id="memoryCode" class="memory-code">Chữ cái đầu sẽ xuất hiện ở đây.</pre><details id="memoryReveal" class="offline-reference"><summary>👁 Hiện văn bản gốc để kiểm tra</summary><div id="memoryOriginal" class="memory-original"></div></details></section></div>`;const input=$('#memoryText'),code=$('#memoryCode'),original=$('#memoryOriginal'),copy=$('#copyMemory');const build=()=>{const text=input.value.trim();if(!text){toast('Hãy nhập đoạn cần học thuộc.');return}const cipher=initialCipher(text);code.textContent=cipher;original.textContent=text;copy.disabled=false;localStorage.setItem('buddy-mnemonic-text',text)};document.querySelectorAll('[data-memory-sample]').forEach(b=>b.onclick=()=>{input.value=mnemonicSamples[b.dataset.memorySample];build()});$('#makeMemoryCode').onclick=build;$('#clearMemory').onclick=()=>{input.value='';code.textContent='Chữ cái đầu sẽ xuất hiện ở đây.';original.textContent='';copy.disabled=true;localStorage.removeItem('buddy-mnemonic-text')};copy.onclick=()=>navigator.clipboard.writeText(code.textContent).then(()=>toast('Đã sao chép mật mã.'));if(saved)build();bindCommon()}
const renderBeforeBuddySpace=render;render=function(){if(view==='buddy')renderBuddySpace();else if(view==='tourguide')renderTourGuide();else if(view==='mnemonic')renderMnemonic();else renderBeforeBuddySpace()};
